<?php require 'config.php';require_login();$u=$_SESSION['user'];$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)){try{$q=$pdo->prepare('UPDATE users SET full_name=?,email=? WHERE id=?');$q->execute([$name,$email,$u['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;$u=$_SESSION['user'];$notice='Profile updated.';}catch(PDOException $e){$notice='Email is already in use.';}}else $notice='Enter a valid name and email.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile</title><style>body{font-family:Arial,sans-serif;background:#f3f6fb;margin:0;color:#17243b}.wrap{max-width:650px;margin:45px auto;background:white;padding:32px;border-radius:16px;box-shadow:0 8px 30px #182c4a18}h1{color:#174c88}label{display:block;margin:14px 0 6px;font-weight:bold}input,select{box-sizing:border-box;width:100%;padding:11px;border:1px solid #c9d3e0;border-radius:7px}button{margin-top:18px;background:#1767b1;color:white;border:0;padding:12px 22px;border-radius:7px;cursor:pointer}.msg{background:#fff3cd;padding:12px;border-radius:7px;margin:12px 0}.nav{margin-bottom:20px}.nav a{margin-right:14px;color:#1767b1}</style></head><body><main class="wrap"><div class="nav"><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></div><h1>Your Profile</h1><?php if($notice):?><div class="msg"><?=e($notice)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Student ID</label><input value="<?=e($u['student_id'])?>" disabled><label>Full Name</label><input name="name" value="<?=e($u['name'])?>" required><label>Email</label><input name="email" type="email" value="<?=e($u['email'])?>" required><label>Department</label><input value="<?=e($u['department'])?>" disabled><label>Semester</label><input value="<?=e($u['semester'])?>" disabled><button>Save Profile</button></form></main></body></html>